/* @lc app=leetcode id=3621 lang=kotlin */ class Solution { fun popcountDepth(n: Long, k: Int): Long = Array(61) { LongArray(61) }.also { c -> (0..60).forEach { i -> (0..i).forEach { j -> c[i][j] = if (j == 0 || j == i) 1L else c[i - 1][j - 1] + c[i - 1][j] } } }.let { C -> if (k == 0) 1L else (1..50).filter { c -> generateSequence(c to 0) { (v, d) -> if (v == 1) null else Integer.bitCount(v) to d + 1 }.last().second == k - 1 }.sumOf { c -> (62 downTo 0).fold(0 to 0L) { (ones, acc), b -> if (n shr b and 1L == 1L) (ones + 1) to (acc + (if (c - ones in 0..b) C[b][c - ones] else 0L)) else ones to acc }.let { (ones, acc) -> acc + (if (ones == c) 1L else 0L) } - (if (k == 1 && c == 1) 1L else 0L) } } }